"""Checks for the dependency-free GSM8K \\boxed{} reward in math_verify_reward.py.

Run with: python3 rewards/test_math_verify_reward.py
"""

import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from math_verify_reward import compute_score  # noqa: E402

BS = "\\"


class TestComputeScore(unittest.TestCase):
    def score(self, gold, response):
        return compute_score("openai/gsm8k", response, gold)

    def test_exact_boxed_match(self):
        self.assertEqual(self.score("18", f"reasoning{BS}boxed{{18}}"), 1.0)

    def test_wrong_number(self):
        self.assertEqual(self.score("7", f"{BS}boxed{{9}}"), 0.0)

    def test_no_box_is_zero(self):
        self.assertEqual(self.score("7", "the answer is 7"), 0.0)

    def test_last_box_wins(self):
        self.assertEqual(self.score("18", f"{BS}boxed{{3}} then {BS}boxed{{18}}"), 1.0)
        self.assertEqual(self.score("18", f"{BS}boxed{{18}} then {BS}boxed{{3}}"), 0.0)

    def test_latex_decorations(self):
        self.assertEqual(self.score("44", f"{BS}({BS}boxed{{44}}{BS})."), 1.0)
        self.assertEqual(self.score("5", f"{BS}boxed{{{BS}text{{5}}}}"), 1.0)
        self.assertEqual(self.score("5", f"{BS}boxed{{{BS}${5}}}"), 1.0)
        self.assertEqual(self.score("12", f"{BS}boxed{{{BS}left( 12 {BS}right)}}"), 1.0)

    def test_numeric_equivalence(self):
        self.assertEqual(self.score("1234", f"{BS}boxed{{1,234}}"), 1.0)
        self.assertEqual(self.score("72", f"{BS}boxed{{72.0}}"), 1.0)
        self.assertEqual(self.score("2.50", f"{BS}boxed{{2.5}}"), 1.0)
        self.assertEqual(self.score("0.5", f"{BS}boxed{{{BS}frac{{1}}{{2}}}}"), 1.0)

    def test_sign_matters(self):
        self.assertEqual(self.score("-4", f"{BS}boxed{{-4}}"), 1.0)
        self.assertEqual(self.score("4", f"{BS}boxed{{-4}}"), 0.0)

    def test_percent_is_decoration_not_scaling(self):
        self.assertEqual(self.score("50", f"{BS}boxed{{50{BS}%}}"), 1.0)

    def test_empty_and_truncated_box(self):
        self.assertEqual(self.score("3", f"{BS}boxed{{}}"), 0.0)
        self.assertEqual(self.score("8", f"cut off {BS}boxed{{8"), 0.0)

    def test_none_solution(self):
        self.assertEqual(self.score("5", None), 0.0)

    def test_nested_braces_inside_box(self):
        self.assertEqual(self.score("18", f"{BS}boxed{{18}} extra {{{{braces}}}}"), 1.0)


if __name__ == "__main__":
    unittest.main(verbosity=2)

